    ('{"old_value": 100.0, "new_value": 101.0}', '1'),
    ('{"old_value": 100.0, "new_value": 99.0}', '-1'),
    ('{"old_value": 1.5, "new_value": 2.5}', '66.7'),
    ('{"old_value": 10.0, "new_value": 10.0001}', '0'),
    ('{"old_value": 99.99, "new_value": 2.5}', '-97.5'),
    ('{"old_value": 2.675, "new_value": 99.99}', '3637.9'),
    ('{"old_value": 0.5, "new_value": 0.0}', '-100'),
    ('{"old_value": 1.005, "new_value": 1.0}', '-0.5'),
    ('{"old_value": 99.99, "new_value": 0.0}', '-100'),
